from math import ceil
from taf.ul.ettf.sim.core.command import Command
from taf.ul.ettf.sim.core.library import State
from taf.ul.ettf.sim.simulators.egate import EgateCommand
from taf.ul.ettf.throughput.common_throughput import CommonThroughput
from taf.ul.ettf.typed.custom_types import ThroughputValue
from taf.ul.ettf.typed.typed import typed
from taf.ul.ettf.logger import custom_logger

logger = custom_logger('traffic')
MAX_PACKAGE_BYTES = 150000000


class PartialTrafficCommand(EgateCommand):
    pass


class TrafficStartCommand(EgateCommand):
    @typed(throughput=ThroughputValue())
    def __init__(self, ue_id, direction, throughput):
        super(TrafficStartCommand, self).__init__(
            command='trf_data_start ue={} dir={}'.format(ue_id, direction), validators=None, parser=None)
        self._throughput = throughput
        self._partial_commands = []
        Command.command_elements.add_modulator('retry', 2)

    def run(self, simulator):
        try:
            self.assemble_command()
            self._run(simulator)
        finally:
            self.clear()

    def clear(self):
        super(TrafficStartCommand, self).clear()
        self._partial_commands = []

    def _run(self, simulator):
        self._prepare_partial_commands()
        self._execute(simulator)

    def _prepare_partial_commands(self):
        throughput_left = int(self._throughput)
        for idx in range(int(ceil(self._throughput / MAX_PACKAGE_BYTES))):
            package, throughput_left = self._calculate_package(throughput_left)
            self._partial_commands.append(self._get_partial_traffic_command(idx, package))

    def _get_partial_traffic_command(self, idx, package):
        command = PartialTrafficCommand(self.command)
        command.update_param('trf_id', idx + 1)
        command.update_param('bps', package)
        command.assemble_command()
        return command

    def _execute(self, simulator):
        for command in self._partial_commands:
            logger.info('Executing simulator command: {}'.format(command.command))
            simulator.execute_command(command)

    @staticmethod
    def _calculate_package(throughput_left):
        if throughput_left >= MAX_PACKAGE_BYTES:
            return MAX_PACKAGE_BYTES, throughput_left - MAX_PACKAGE_BYTES
        return throughput_left, 0


class TrafficStopCommand(EgateCommand):
    def __init__(self, ue_id):
        super(TrafficStopCommand, self).__init__('trf_data_stop ue={}'.format(ue_id))


class TrafficOptions(State):
    def with_bearer_id(self, bearer_id):
        self.append_command_attribute('id', bearer_id)

    def with_group(self, group):
        self.append_command_attribute('_group_', group)

    def with_pdu(self, pdu):
        self.append_command_attribute('pdu', pdu)

    def with_qfi(self, qfi):
        self.append_command_attribute('qfi', qfi)

    def with_cl_bearer_stats(self):
        self.append_command_attribute('cl_bearer_stats', 'on')

    def with_cl_qfi_stats(self):
        self.append_command_attribute('cl_qfi_stats', 'on')

    def without_cl_trf_stats(self):
        self.append_command_attribute('cl_trf_stats', 'off')

    def with_rtp_codec(self, rtp_codec):
        self.append_command_attribute('rtp_codec', rtp_codec)

    def with_ssrc(self, ssrc):
        self.append_command_attribute('ssrc', ssrc)

    def with_rtp_voice_silence(self, rtp_voice_silence):
        self.append_command_attribute('rtp_voice_silence', rtp_voice_silence)

    def with_protocol(self, protocol):
        self.append_command_attribute('protocol', protocol)

    def with_ip_version(self, ip_version):
        self.append_command_attribute('ip_version', ip_version)

    def with_trf_id(self, trf_id):
        self.append_command_attribute('trf_id', trf_id)

    def with_direction(self, direction):
        self.append_command_attribute('dir', direction)


class Traffic(State):
    def generate_traffic(self, ue_id, direction, throughput):
        self.init_command(TrafficStartCommand(ue_id, direction, throughput))

    def stop_traffic(self, ue_id):
        self.init_command(TrafficStopCommand(ue_id))


class TrafficThroughput(TrafficOptions, Traffic, CommonThroughput):
    pass


traffic = TrafficThroughput
